return {
  [633595722992128] = "Jornal Homem Honesto de Tingen",
  [633596528298496] = "Relatório sobre o caso de roubo e assassinato",
  [633596796733952] = "De acordo com o departamento de polícia, a cena na casa do Sr. Welch foi horrível. Todo o ouro, joias, dinheiro e quaisquer itens valiosos que fossem fáceis de transportar foram roubados, não deixando nem um centavo de cobre para trás. Há razões para acreditar que este é um grupo de criminosos cruéis e cruéis que não hesitariam em matar qualquer pessoa inocente que visse os seus rostos. \n Uma boa notícia é que o departamento de polícia identificou os culpados e capturou o principal perpetrador. Forneceremos relatórios de acompanhamento o mais rápido possível.",
  [633597333604864] = "Chocante! Uma senhora solitária realmente fez isso!",
  [633598138911232] = "Recrutamento do Coro",
  [633598407349504] = "A polícia aconselha os cidadãos de Tingen a reduzirem as saídas noturnas e a tentarem não permanecer ao ar livre por longos períodos. Recomenda-se viajar em grupos e avisar com antecedência a familiares e amigos sobre seu paradeiro.",
  [633598407346688] = "O coral da Evernight Goddess Church está recrutando. Louve a Deusa e encontre a paz. Os interessados ​​podem ir até...",
  [633598407351040] = "A Igreja da Deusa da Noite Eterna está abrindo aulas gratuitas de alfabetização de adultos a partir de hoje, abertas a todos os cidadãos da cidade. \n O conteúdo do curso inclui alfabetização, aritmética, redação de cartas e leitura guiada das escrituras da igreja. Os interessados ​​podem dirigir-se à Catedral de Santa Selena para se inscrever.",
  [633598407350784] = "　　A polícia emitiu um alerta de emergência sobre viagens noturnas, especialmente para mulheres jovens, aconselhando-as a evitar ao máximo atividades noturnas. É relatado que muitos casos recentes de pessoas desaparecidas ocorreram tarde da noite, e as vítimas receberam convites para namoro desconhecidos antes de desaparecerem.",
  [633598407350528] = "　　Ovos são um alimento familiar para todos. Quando um ovo da sorte é misturado com centenas de outros, você consegue encontrá-lo com precisão? O desafio \"Um em Cem Ovos\" está a todo vapor. Venha e experimente; o próximo “vencedor de dez mil libras” pode ser você!",
  [633598407350272] = "Em uma pequena cidade perto do Lago Golden Autumn, alguém afirmou ter encontrado uma misteriosa sombra negra parecida com um polvo.",
  [633598407350016] = "Um cidadão anônimo de Tingen enviou uma carta a este jornal, pedindo-nos que publicássemos um aviso para encontrar um homem de meia-idade chamado <Highlight> \"Oswald\". </> Ele tem aproximadamente 30-40 anos e está desaparecido desde maio deste ano. Se alguém tiver alguma informação, entre em contato com este jornal.",
  [633598407349760] = "Em preparação para o Festival de Inverno deste ano, a <Highlight> Evernight Goddess Church </> começou a recrutar membros para o coral. Esperamos que você seja um crente devoto da Deusa da Noite Eterna e tenha alguma base para cantar ou recitar. \n Vá à Catedral de Santa Selena para uma entrevista; a igreja fornecerá um subsídio de transporte e refeição de 3 sol.",
  [633598407348736] = "Um pintor \"Colorista\" de Tingen lançou ontem uma nova obra. Em uma pintura de paisagem noturna, ele usou <Highlight> branco prateado </> como a cor da lua, gerando discussão entre muitos...",
  [633598407347712] = "　　O romance de mistério, romance e fantasia \"Storm Manor\" já está à venda!\n　　O romance conta a história da heroína Cici entrando na Frieze Manor como tutora. Foi amplamente elogiado pelos leitores e entrou na lista dos mais vendidos deste ano.",
  [633598407347200] = "As vagas eletivas para \"História Geral\" do Professor William Hamer foram <Highlight> todas preenchidas </>. Alunos que não foram selecionados, prestem atenção e inscrevam-se em outros cursos a tempo, e não perturbem a ordem normal de ensino do Professor William Hamer.",
  [633598407346944] = "Quando vier ao Restaurante Coastline, não deixe de provar os legumes fritos na banha. \n O cozinheiro irá ferver a banha e selá-la por vários dias antes de adicioná-la aos vegetais. Os vegetais fritos com banha resultantes são incomparáveis ​​tanto em sabor quanto em textura.",
  [633598138915584] = "Evernight Church abre aulas de alfabetização para adultos",
  [633598138915328] = "Apelo policial: cuidado ao viajar à noite",
  [633598138915072] = "Um em cem ovos, esperando pelo seu desafio!",
  [633598138914816] = "Sombras à beira do lago",
  [633598138914304] = "Recrutamento do Coro Evernight Goddess",
  [633598138914048] = "Apelo Policial",
  [633598138913280] = "\"Escola de Cores\" desperta discussão!",
  [633598138912256] = "\"Storm Manor\" em alta venda",
  [633598138911744] = "Anúncio de Seleção de Curso",
  [633598138911488] = "Ingredientes selecionados criam iguarias de primeira linha",
  [633597602044672] = "　　Os espelhos de cobre comemorativos do Festival de Drama geraram recentemente uma mania de coleção no mercado de segunda mão, com o preço mais alto chegando a meia libra de ouro.\n　　\"O espelho de cobre que ganhei antes foi perdido sem motivo, caso contrário, eu poderia ter obtido um pequeno lucro!\" reclamou um cidadão. É relatado que um grande número de imitações entrou no mercado. Lembramos ao público que consuma racionalmente e tome cuidado para não ser enganado.",
  [633597602044416] = "O último romance de vampiros, \"Guest Under the Moon\", gerou um frenesi de compras! As cenas românticas descritas no livro, como “Black Rose Invitation” e “Picnic Under the Moon”, estão se tornando uma nova tendência para os jovens expressarem seu amor.",
  [633597602044160] = "Recentemente, o Departamento de Polícia da cidade de Tingen recebeu vários relatos de adolescentes acendendo velas em banheiros públicos e orando a uma divindade desconhecida que se autodenomina “Senhor do Banheiro”. A polícia lembra aos cidadãos: Por favor, estabeleçam crenças corretas e mantenham-se afastados de todas as atividades de oração pouco ortodoxas.",
  [633597602043648] = "De acordo com notícias oficiais, um <Highlight> estudante de engenharia mecânica </> da Universidade de Tingen desapareceu há vários dias. Professores e alunos da escola afirmaram que a desaparecida Iris era uma <Highlight> \"fanática entusiasta da mecânica\". </> Alguém mencionou que ela parecia ter falado sobre ir para <Highlight> \"uma base maravilhosa\" </> para conduzir uma \"expedição\". \n Se você tiver alguma informação, entre em contato com a polícia o mais rápido possível.",
  [633597602043392] = "À medida que o Festival de Drama do <Highlight> Imperador Roselle </> se aproxima, os principais jornais de Tingen estão competindo para revisitar sua gloriosa história. Este imperador estrangeiro de há mais de cem anos empurrou as marés da Revolução Industrial para varrer os países do Continente Norte. \n A era do vapor estrondoso, a era do grande imperador Roselle, parece ter retornado!",
  [633597602043136] = "Recentemente, um cidadão desta cidade desmaiou repentinamente em um local adivinhação e foi levado às pressas para o hospital. O repórter soube que o cidadão está em coma há mais de sete dias. Os seus sinais vitais estão estáveis, mas a causa específica da doença permanece obscura. \n O hospital e a polícia estabeleceram uma equipe conjunta de investigação para determinar a causa do incidente o mais rápido possível.",
  [633597602042368] = "　　Hoje, a loja de departamentos Harold estocou novos vestidos femininos, camisas e terninhos masculinos, bem como cartolas de seda e bengalas com incrustações de ouro que todo cavalheiro deve ter. A respeito disso, o chefe disse: \"Esses produtos são os estilos mais recentes importados do exterior. Todos são bem-vindos para vir e fazer compras.\"...",
  [633597602041344] = "Ótimas notícias! Ótimas notícias! Após meses de reforma, a loja de departamentos Harold, localizada no distrito de Howls Street, em Tingen, foi inaugurada hoje! \n Estamos lançando uma grande promoção: ganhe uma libra de desconto para cada dez libras gastas! Ao longo de julho, a loja de departamentos Harold terá surpresas e descontos constantes, e há muitos prêmios esperando para você reivindicar!",
  [633597602040832] = "A peça histórica “Imperador Salomão”, dirigida pelo professor William Hamer, terá estreia na próxima quarta-feira, às 20h, no teatro do campus. Dado o <Highlight> número excessivo de reservas </> , o canal normal de aplicação está agora fechado e um método de distribuição <Highlight> de acesso público, por ordem de chegada </> será implementado. Esperamos que os alunos se informem. \n",
  [633597602040576] = "Para \"dons naturais\" que outros chefs não ousam experimentar, Cook é sempre o primeiro a coletá-los, colhê-los, escavá-los, pegá-los e cozinhá-los da maneira mais maravilhosa. \n Sua persistência na comida gourmet faz de Cook o verdadeiro Rei dos Chefs.",
  [633597602040320] = "... <Highlight> Sra. Bates </> foi às compras no mercado negro e foi fraudada, gastando uma grande soma de dinheiro para comprar itens inúteis como <Highlight> sangue de peixe </> . Dois dias depois, a Sra. Bates <Highlight> desapareceu </>, supostamente tendo fugido de casa após descobrir que havia sido enganada. É relatado que a Sra. Bates estava agindo de forma estranha, suspeita de sofrer de <Highlight> doença mental </> ...",
  [633597333609216] = "Lembranças de festivais de teatro inesperadamente populares, preços de mercado de segunda mão aumentam dez vezes",
  [633597333608960] = "Festa do amor: romances de vampiros provocam outra onda",
